insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('98c8920b-c308-4759-a23c-1968fcafd7ed', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$de overheid bouwt de gasproductie versneld af en wil het gasverbruik sterk verminderen$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context1.png$$,
   $$De overheid van een land heeft het klimaatakkoord van Parijs getekend. De overheid heeft daarom het besluit genomen om de eigen gasproductie versneld af te bouwen en gezinnen en bedrijven in het land te stimuleren om het verbruik van gas sterk te verminderen.$$, 'inline'),
  ('a31a026a-1fbc-4182-af21-df21d767ad4a', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$terugval in aardgasinkomsten leidt zonder maatregelen tot een overheidstekort$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context2.png$$,
   $$Voor de overheid leidt de terugval in aardgasinkomsten tot een financiële tegenvaller op de begroting van miljarden euro’s per jaar. Zonder extra maatregelen ontstaat hierdoor een overheidstekort.$$, 'inline'),
  ('cad00e73-7d12-4810-b301-f3cfcfbdb9b6', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$verhoging energiebelasting op gas; prijselasticiteit −0,1 en gemiddeld verbruik 1.466 m³$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context3.png$$,
   $$Met een verhoging van de energiebelasting op gasverbruik kan de overheid gezinnen en bedrijven stimuleren om minder gas te verbruiken en te kiezen voor alternatieve energiebronnen. Het effect ervan is afhankelijk van de prijselasticiteit van de vraag naar gas. Voor een gemiddeld gezinshuishouden is de prijselasticiteit van de vraag naar gas −0,1. Het jaarlijkse gasverbruik is gemiddeld 1.466 m³ per gezinshuishouden.$$, 'inline'),
  ('cd5a846b-dcd6-4190-9746-d90fca780e6d', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$doel: gasverbruik −5% door de energiebelasting met 75% te verhogen$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context4.png$$,
   $$De overheid stelt zich ten doel het gasverbruik in kubieke meter (m³) van een gemiddeld gezinshuishouden te verminderen met 5% en wil daartoe de huidige energiebelasting op gas met 75% verhogen.$$, 'inline'),
  ('70fb598c-392b-481a-807a-40ed9c7dbb7b', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$een analist: economische groei beïnvloedt de effectiviteit van het beleid$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context5.png$$,
   $$Een analist van het ministerie van economische zaken benadrukt dat economische groei van invloed is op de effectiviteit van het overheidsbeleid om de vraag naar gas van gezinnen en bedrijven te verminderen. De analist doet drie uitspraken:$$, 'inline'),
  ('5e877a54-d031-4271-9a01-98794ee8c8f9', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$drie uitspraken van de analist over economische groei, subsidies en energiebelasting$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context6.png$$,
   $$− Uitspraak 1: Economische groei kan enerzijds tot meer gasverbruik en anderzijds tot minder gasverbruik leiden.
− Uitspraak 2: Economische groei maakt het voor de overheid makkelijker om subsidies te financieren.
− Uitspraak 3: Subsidies op energiezuinige productietechnologieën en de verhoging van de energiebelasting op gasverbruik van gezinnen en bedrijven, hebben zelf ook weer effect op de economische groei van het land.$$, 'inline'),
  ('c395d0dd-4b2e-4601-9c28-2e78eeb0a667', 'f85cd0ca-f63a-403d-b7ee-19affe9bf052', $$bron 1: prijsopbouw van gas per m³ vóór verhoging van de energiebelasting$$,
   $$economie-havo-2023-ii-stoppen-met-aardgas-dwingt-tot-keuzes-context7.png$$,
   $$Bron 1 prijsopbouw van gas per kubieke meter (m³) vóór verhoging van de energiebelasting
levering en transport gas | € 0,452
energiebelasting | € 0,346 +
SUBTOTAAL: tarief exclusief 21% btw | € 0,798
btw 21% over € 0,798 | € 0,168 +
TOTAAL: tarief inclusief 21% btw | € 0,966$$, 'inline'),
  ('fef2d000-e45b-4731-a398-e28476ec11f9', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$uit een krant$$,
   $$economie-havo-2023-ii-vliegtaks-context1.png$$,
   $$Uit een krant:$$, 'inline'),
  ('3492041b-3512-46e7-8dba-987b80b758e4', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$plan voor een vliegtaks van € 7,50 per vliegticket om de uitstoot te verlagen$$,
   $$economie-havo-2023-ii-vliegtaks-context2.png$$,
   $$De Nederlandse overheid heeft het plan om een vliegbelasting van € 7,50 per vliegticket in te voeren voor alle vluchten vanaf een Nederlandse luchthaven: de vliegtaks. De luchtvaartmaatschappijen berekenen de heffing door in de eindprijs van een vliegticket en moeten vervolgens per verkocht ticket € 7,50 afdragen aan de belastingdienst. Het doel van de vliegtaks is om het vliegen voor passagiers minder aantrekkelijk te maken en zo de uitstoot van broeikasgassen te verlagen.$$, 'inline'),
  ('5e625a72-1dc5-4527-8cdb-377716c05cc8', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$onderzoeksbureau: milieueffect op korte termijn verwaarloosbaar (met noot bezettingsgraad)$$,
   $$economie-havo-2023-ii-vliegtaks-context3.png$$,
   $$Een onderzoeksbureau analyseert de effecten van de vliegtaks op het milieu en trekt de conclusie dat deze op de korte termijn verwaarloosbaar klein zijn als bij elke vlucht alleen de bezettingsgraad van de vliegtuigen zal dalen.
noot bezettingsgraad = het feitelijke aantal bezette stoelen afgezet tegen het beschikbare aantal stoelen$$, 'inline'),
  ('f6aea6d1-92aa-420b-9d56-6f8e6176c87f', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$ticket Schiphol-Rome € 300; prijselasticiteit van de vraag −1,4$$,
   $$economie-havo-2023-ii-vliegtaks-context4.png$$,
   $$Passagiers die vanaf de Nederlandse luchthaven Schiphol naar Rome vliegen, betalen bij luchtvaartmaatschappij Linea Azzurra een prijs van € 300 voor een vliegticket. De prijselasticiteit van de vraag naar deze vliegtickets van Schiphol naar Rome is −1,4.$$, 'inline'),
  ('6e289428-3155-49b0-b55e-5d64505b19a8', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$voorstel: vliegtaks laten afhangen van de afstand van de vlucht$$,
   $$economie-havo-2023-ii-vliegtaks-context5.png$$,
   $$Volgens een aantal politieke partijen kan het directe effect van de vliegtaks op het milieu worden vergroot door de hoogte van de vliegtaks af te laten hangen van de afstand van de vlucht.$$, 'inline'),
  ('e605243e-9897-4c04-88e3-ee4260bea40e', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$debat tussen de Gele Partij en de Witte Partij over de hoogte van de vliegtaks$$,
   $$economie-havo-2023-ii-vliegtaks-context6.png$$,
   $$Twee politieke partijen gaan met elkaar in debat.
− De Gele Partij zegt: Om eenzelfde daling van de vraag te realiseren, is voor lange vluchten een andere vliegtaks op vliegtickets nodig dan voor korte vluchten, omdat de vraag naar tickets voor lange vluchten minder prijselastisch is dan die naar tickets voor korte vluchten.
− De Witte Partij zegt: Belast juist de tickets voor korte vluchten met een hogere vliegtaks. Een partijlid stelt: “Deze maatregel zal leiden tot een grotere daling van de vraag naar vliegtickets, omdat er voor kortere vluchten meer substitutiegoederen en -diensten zijn.”$$, 'inline'),
  ('08b0ca45-9af3-4790-8aa3-a9d6c4e95baf', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$de Witte Partij baseert haar standpunt op substitutiegoederen$$,
   $$economie-havo-2023-ii-vliegtaks-context7.png$$,
   $$De Witte Partij baseert haar standpunt op de beschikbaarheid van substitutiegoederen en -diensten.$$, 'inline'),
  ('3f1e373c-807d-4b3e-8d01-6dac3999f211', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$luchtvaartmaatschappijen: de vliegtaks gaat ten koste van hun winst$$,
   $$economie-havo-2023-ii-vliegtaks-context8.png$$,
   $$De luchtvaartmaatschappijen protesteren tegen de voorgestelde vliegtaks van € 7,50 per vliegticket, en stellen dat deze taks ten koste gaat van hun winst en alleen goed is voor de Nederlandse schatkist. Om het effect op de winst te verklaren, tonen zij een marktmodel met een vraag- en aanbodfunctie.$$, 'inline'),
  ('2863f53d-173f-490c-9269-62b297e660ac', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$marktmodel met vraag- en aanbodfuncties vóór en na invoering vliegtaks$$,
   $$economie-havo-2023-ii-vliegtaks-context9.png$$,
   $$Marktmodel met vraag- en aanbodfuncties
Qv = −P + 480
Qa vóór invoering vliegtaks = 2P − 105
Qa na invoering vliegtaks = 2P − 120
Er geldt dat Qv = Qa
P = gemiddelde prijs van een vliegticket in euro’s
Q = aantal vliegtickets vanuit Nederlandse luchthavens x 10.000$$, 'inline'),
  ('08549248-e7dd-4523-96fa-a686c5fd3a15', '9563669a-1400-4238-8110-0f0f6e70c1c5', $$de vliegtaks kan niet volledig in de ticketprijs worden doorberekend$$,
   $$economie-havo-2023-ii-vliegtaks-context10.png$$,
   $$Op basis van dit marktmodel stellen de luchtvaartmaatschappijen dat ze de vliegtaks niet volledig kunnen doorberekenen in de prijs van een vliegticket.$$, 'inline'),
  ('60e5168f-2187-4e48-9a86-f24ad54a2d43', 'cc1d0255-6eb0-40a1-98e1-b91d803b3a6f', $$heffingskortingen zijn tussen 2014 en 2017 inkomensafhankelijker gemaakt (zie bron 1)$$,
   $$economie-havo-2023-ii-heffingskortingen-inkomensafhankelijk-context1.png$$,
   $$Iedereen in Nederland die inkomstenbelasting moet betalen, heeft recht op één of meer heffingskortingen. Naast de algemene heffingskorting hebben belastingplichtigen die betaald werk verrichten ook recht op een arbeidskorting. Tussen 2014 en 2017 heeft de regering de hoogte van beide heffingskortingen inkomensafhankelijker gemaakt (zie bron 1). Dit heeft effect op de arbeidsmarkt. De regering stelt: “De aanpassing van de arbeidskorting voor inkomens tot en met € 80.000 kan ertoe leiden dat meer mensen zich zullen aanbieden op de arbeidsmarkt.”$$, 'inline'),
  ('33cfcb13-3ec8-4e2c-a4fc-093465094d08', 'cc1d0255-6eb0-40a1-98e1-b91d803b3a6f', $$oorzaak-gevolgschema: invloed van de verhoogde arbeidskorting op de arbeidsvraag$$,
   $$economie-havo-2023-ii-heffingskortingen-inkomensafhankelijk-context2.png$$,
   $$Onderstaand oorzaak-gevolg schema toont de invloed van de verhoogde arbeidskorting (bij inkomens tot en met € 80.000) op de arbeidsvraag.$$, 'inline'),
  ('c2fe70d0-ae2a-4fea-b7d2-18f6ebe9cfab', 'cc1d0255-6eb0-40a1-98e1-b91d803b3a6f', $$schema: arbeidskorting stijgt → (a) → conjunctuurzijde (b)-(c) / structuurzijde (d)-(e)-(f) → productie stijgt → vraag naar arbeid neemt toe$$,
   $$economie-havo-2023-ii-heffingskortingen-inkomensafhankelijk-context3.png$$,
   $$oorzaak-gevolgschema:
arbeidskorting stijgt → (a) → conjunctuurzijde: (b) → (c) → productie stijgt → vraag naar arbeid neemt toe
arbeidskorting stijgt → (a) → structuurzijde: (d) → (e) → (f) → productie stijgt → vraag naar arbeid neemt toe$$, 'inline'),
  ('7da4d532-e648-42c3-bda6-8e73e6a2863c', 'cc1d0255-6eb0-40a1-98e1-b91d803b3a6f', $$nivellerend effect van belastingheffing bij inkomens van € 120.000 en € 20.000$$,
   $$economie-havo-2023-ii-heffingskortingen-inkomensafhankelijk-context4.png$$,
   $$Belastingheffing kan een nivellerend effect hebben op de inkomensverdeling. Een belastbaar inkomen van € 120.000 is zes keer zo hoog als een belastbaar inkomen van € 20.000 (zie bron 1 en bron 2). Een werknemer met een belastbaar inkomen van € 120.000 had in 2013 een netto-inkomen van € 66.744. Een werknemer met een belastbaar inkomen van € 20.000 had in 2013 een netto-inkomen van € 16.317. Daarmee was het netto-inkomen van het hogere inkomen 4,1 keer zo hoog als het netto-inkomen van het lagere inkomen. Door de belastingwijziging is er in 2014 sprake van een toegenomen nivellering voor de belastbare inkomens € 120.000 en € 20.000.$$, 'inline'),
  ('737c99e3-c0ba-4d9c-b941-8f066ff125b3', 'cc1d0255-6eb0-40a1-98e1-b91d803b3a6f', $$CPB: de economie groeit; in 2017 hoogconjunctuur$$,
   $$economie-havo-2023-ii-heffingskortingen-inkomensafhankelijk-context5.png$$,
   $$Het Centraal Planbureau (CPB) voorspelde dat in 2014 en volgende jaren de Nederlandse economie zal groeien. Stel dat deze voorspelling uit is gekomen en dat in 2017 de Nederlandse economie in de fase van hoogconjunctuur verkeerde.$$, 'inline'),
  ('ec63f15e-8a7d-4fbd-9098-2a4d809437fc', 'cc1d0255-6eb0-40a1-98e1-b91d803b3a6f', $$bron 1: heffingskortingen 2013 t/m 2017$$,
   $$economie-havo-2023-ii-heffingskortingen-inkomensafhankelijk-context6.png$$,
