   $$economie-havo-2023-ii-vliegtaks-vraag6.png$$, $$1p 6 Geef een verklaring voor de conclusie van het onderzoeksbureau.$$, array['fef2d000-e45b-4731-a398-e28476ec11f9', '3492041b-3512-46e7-8dba-987b80b758e4', '5e625a72-1dc5-4527-8cdb-377716c05cc8']::uuid[]),
