   $$economie-havo-2023-ii-vliegtaks-vraag10.png$$, $$3p 10 Bereken hoeveel procent van de vliegtaks voor rekening van de luchtvaartmaatschappijen komt. Bereken daartoe eerst de oude en de nieuwe evenwichtsprijs.$$, array['3f1e373c-807d-4b3e-8d01-6dac3999f211', '2863f53d-173f-490c-9269-62b297e660ac', '08549248-e7dd-4523-96fa-a686c5fd3a15']::uuid[]),
