   $$economie-havo-2023-ii-vliegtaks-vraag11.png$$, $$2p 11 Bereken de opbrengst van de vliegtaks voor de Nederlandse schatkist.$$, array['3492041b-3512-46e7-8dba-987b80b758e4', '2863f53d-173f-490c-9269-62b297e660ac']::uuid[]),
